+// API keys and roles. A key in `apiKeys` has a `name` (shown in the audit
+// log) and a `role`. Each route needs one permission:
+//   read    - look at data (every GET)
+//   kitchen - cook recipes, record waste, log temperatures, enter counts
+//   manage  - everything else
+// viewer may read, cook may also do kitchen work, manager may do everything.
+
+const GRANTS = Object.freeze({
+  viewer: ["read"],
+  cook: ["read", "kitchen"],
+  manager: ["read", "kitchen", "manage"],
+});
+
+/** Roles a key may have. */
+export const ROLES = Object.freeze(Object.keys(GRANTS));
+
+/** The API key record for `key`, or null when there is none. */
+export function findKey(store, key) {
+  if (typeof key !== "string" || key === "") return null;
+  return (store.data.apiKeys ?? []).find((k) => k.key === key) ?? null;
+}
+
+/** Whether `role` holds `permission` ("read", "kitchen" or "manage"). */
+export function allows(role, permission) {
+  return (GRANTS[role] ?? []).includes(permission);
+}
