@@ -0,0 +1,64 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, auth } from "./helpers.js";
+
+test("no key or an unknown key is 401", async () => {
+  const { raw } = app();
+  const a = await raw({ path: "/items" });
+  assert.equal(a.status, 401);
+  assert.equal(a.body.error.code, "unauthorized");
+  const b = await raw({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(b.status, 401);
+  const c = await raw({ method: "POST", path: "/nope", headers: {} });
+  assert.equal(c.status, 401);
+});
+
+test("a viewer may only read", async () => {
+  const { raw, store } = app();
+  assert.equal((await raw({ path: "/items", headers: auth("viewer") })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const res = await raw({ method: "POST", path: "/recipes/1/cook", headers: auth("viewer"), body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+  assert.equal((await raw({ path: "/audit", headers: auth("viewer") })).status, 403);
+});
+
+test("a cook may cook, waste, log temperatures and count, but not more", async () => {
+  const { raw, handle } = app();
+  const h = auth("cook");
+  assert.equal((await raw({ method: "POST", path: "/recipes/1/cook", headers: h, body: { portions: 1 } })).status, 200);
+  assert.equal((await raw({ method: "POST", path: "/batches/1/waste", headers: h, body: { qty: 1 } })).status, 201);
+  assert.equal((await raw({ method: "POST", path: "/temperatures", headers: h, body: { location: "fridge", celsius: 3 } })).status, 201);
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await raw({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: h, body: { batchId: 6, counted: 12 } })).status, 200);
+  assert.equal((await raw({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: h })).status, 403);
+  assert.equal((await raw({ method: "POST", path: "/orders", headers: h, body: { supplierId: 1, lines: [] } })).status, 403);
+  assert.equal((await raw({ path: "/audit", headers: h })).status, 403);
+});
+
+test("changes are audited, newest first, for managers", async () => {
+  const { raw, handle } = app();
+  await raw({ method: "POST", path: "/recipes/1/cook", headers: auth("cook"), body: { portions: 1 } });
+  await raw({ method: "POST", path: "/recipes/2/cook", headers: auth("cook"), body: { portions: 100 } });
+  await raw({ method: "POST", path: "/orders/1/send", headers: auth("viewer") });
+  await raw({ method: "POST", path: "/recipes/1/cook", headers: {} });
+  await handle({ path: "/items" });
+  const res = await handle({ path: "/audit" });
+  assert.equal(res.status, 200);
+  assert.deepEqual(res.body.map((e) => [e.keyName, e.method, e.path, e.status]), [
+    ["front-of-house", "POST", "/orders/1/send", 403],
+    ["line-cook", "POST", "/recipes/2/cook", 409],
+    ["line-cook", "POST", "/recipes/1/cook", 200],
+  ]);
+  assert.equal(res.body[0].at, "2026-10-28T10:00:00.000Z");
+});
+
+test("a failed change is rolled back but still audited", async () => {
+  const { handle, store } = app();
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/2/cook", body: { portions: 100 } });
+  assert.equal(res.status, 409);
+  assert.equal(JSON.stringify(store.data.batches), before);
+  assert.equal(store.data.audit.length, 1);
+});
